1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	
45	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
46	  alikeItems.length === BLOCK_SIZE;
47	
48	const sumOfBasePremiums = (items: Item[]): number =>
49	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
50	
51	const CURSE_SURCHARGE_RATE = 0.5;
52	const HIGH_ENCHANTMENT_LEVEL = 5;
53	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
54	
55	const isCursed = (item: Item): boolean => item.cursed === true;
56	
57	const isHighlyEnchanted = (item: Item): boolean =>
58	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
59	
60	// Every item-specific surcharge is a rate on THAT item's base premium, charged
61	// when its risk applies. Adding a new one means adding a row here — nothing else.
62	type ItemSurcharge = { appliesTo: (item: Item) => boolean; rate: number };
63	
64	const ITEM_SURCHARGES: ItemSurcharge[] = [
65	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
66	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
67	];
68	
69	const surchargeRateOn = (item: Item): number =>
70	  ITEM_SURCHARGES.reduce(
71	    (rate, surcharge) => (surcharge.appliesTo(item) ? rate + surcharge.rate : rate),
72	    0,
73	  );
74	
75	const itemSurchargesOn = (items: Item[]): number =>
76	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
77	
78	const typesOf = (items: Item[]): string[] => [...new Set(items.map((item) => item.type))];
79	
80	const groupedByType = (items: Item[]): Item[][] =>
81	  typesOf(items).map((type) => items.filter((item) => item.type === type));
82	
83	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
84	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
85	
86	const policyBaseOf = (items: Item[]): number =>
87	  groupedByType(items).reduce((sum, group) => sum + basePremiumOfAlikeItems(group), 0);
88	
89	// Rounding always favours the MHPCO: premiums up, payouts down.
90	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
91	
92	const firstInsuranceSurchargeOn = (policyBase: number): number =>
93	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
94	
95	// Policy-wide modifiers are percentages of the UNMODIFIED policy base — never of
96	// a base that already includes the item surcharges.
97	const policyModifiersOn = (policyBase: number): number =>
98	  firstInsuranceSurchargeOn(policyBase);
99	
100	const quoteFor = (items: Item[]): Result => {
101	  const policyBase = policyBaseOf(items);
102	  return {
103	    premium: premiumRoundedInMHPCOsFavour(
104	      policyBase + itemSurchargesOn(items) + policyModifiersOn(policyBase) + PROCESSING_FEE,
105	    ),
106	  };
107	};
108	
109	const resultFor = (step: Step): Result => {
110	  if (step.op === "quote") return quoteFor(step.items);
111	  throw new Error(`unsupported step: ${step.op}`);
112	};
113	
114	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
115	  results: scenario.steps.map(resultFor),
116	});
