// Items of the same type are "alike"; each group is priced together so a
// building block can be recognised.
const alikeItemGroupsIn = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];
